using System.Windows;using LibraryManager.Models;using LibraryManager.Services;namespace LibraryManager.Views;public partial class ReturnConfirmDialog:Window{public PaymentMethod? Method;public bool PayNow;public ReturnConfirmDialog(Loan loan){InitializeComponent();var amount=new LoanService().CalculateFine(loan,DateTime.Now);Form.Children.Add(new System.Windows.Controls.TextBlock{Text="جریمه: "+amount+" تومان",Margin=new Thickness(8)});var cash=new System.Windows.Controls.RadioButton{Content="پرداخت نقدی",IsChecked=true};var card=new System.Windows.Controls.RadioButton{Content="پرداخت کارتی"};var later=new System.Windows.Controls.RadioButton{Content="پرداخت در آینده (مسدود شدن امانت)"};if(amount>0){Form.Children.Add(cash);Form.Children.Add(card);Form.Children.Add(later);}var b=new System.Windows.Controls.Button{Content="تأیید بازگشت"};b.Click+=(s,e)=>{PayNow=amount<=0||later.IsChecked!=true;if(PayNow&&amount>0)Method=card.IsChecked==true?PaymentMethod.Card:PaymentMethod.Cash;DialogResult=true;};Form.Children.Add(b);}}